<?php
declare(strict_types=1);
$configPath=dirname(__DIR__).'/config/config.php';$config=is_file($configPath)?require $configPath:require dirname(__DIR__).'/config/config.example.php';date_default_timezone_set($config['app']['timezone']??'Asia/Baku');
function h(?string $v):string{return htmlspecialchars($v??'',ENT_QUOTES,'UTF-8');}
$pdo=null;$articles=[];$categories=[];$error=false;$q=trim((string)($_GET['q']??''));$cat=(int)($_GET['category']??0);$page=max(1,(int)($_GET['page']??1));$perPage=9;
try{$d=$config['database'];$pdo=new PDO("mysql:host={$d['host']};dbname={$d['name']};charset={$d['charset']}",$d['username'],$d['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$categories=$pdo->query("SELECT id,name FROM categories WHERE is_active=1 ORDER BY sort_order,name")->fetchAll();
$where=["a.status='published'"];$args=[];if($q!==''){$where[]="(a.title LIKE ? OR a.excerpt LIKE ? OR a.body LIKE ?)";$like='%'.$q.'%';array_push($args,$like,$like,$like);}if($cat>0){$where[]='a.category_id=?';$args[]=$cat;}
$clause=implode(' AND ',$where);$count=$pdo->prepare("SELECT COUNT(*) FROM articles a WHERE $clause");$count->execute($args);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$stmt=$pdo->prepare("SELECT a.title,a.slug,a.excerpt,a.cover_image,a.published_at,a.views,c.name category_name FROM articles a LEFT JOIN categories c ON c.id=a.category_id WHERE $clause ORDER BY a.published_at DESC,a.id DESC LIMIT $perPage OFFSET ".(($page-1)*$perPage));$stmt->execute($args);$articles=$stmt->fetchAll();
}catch(Throwable $e){$error=true;}
function queryUrl(array $changes=[]):string{$params=$_GET;foreach($changes as $k=>$v){if($v===null||$v==='')unset($params[$k]);else $params[$k]=$v;}return 'blog.php'.($params?'?'.http_build_query($params):'');}
