<section class="blog-content"><form class="blog-filters" method="get"><input name="q" value="<?=h($q)?>" placeholder="Məqalə axtar..." aria-label="Məqalə axtar"><select name="category"><option value="0">Bütün kateqoriyalar</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=$cat===(int)$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select><button class="btn btn-primary" type="submit">Axtar</button></form>
<?php if($error):?><p class="empty-content">Məqalələrə hazırda çıxış mümkün deyil. Məlumat bazası sazlanmalıdır.</p><?php elseif($articles):?><div class="blog-list"><?php foreach($articles as $a):?><article class="blog-item"><?php if($a['cover_image']):?><a class="blog-cover" href="article.php?slug=<?=rawurlencode($a['slug'])?>"><img src="<?=h($a['cover_image'])?>" alt="<?=h($a['title'])?>" loading="lazy"></a><?php else:?><a class="blog-cover blog-cover-empty" href="article.php?slug=<?=rawurlencode($a['slug'])?>"><span>RASHADFINANCE</span></a><?php endif;?><div class="blog-item-body"><div class="blog-meta"><?=h($a['category_name']??'Maliyyə')?><span>·</span><?=h($a['published_at']??'')?><span>·</span><?=number_format((int)$a['views'])?> baxış</div><h2><a href="article.php?slug=<?=rawurlencode($a['slug'])?>"><?=h($a['title'])?></a></h2><p><?=h($a['excerpt'])?></p><a class="arrow-link" href="article.php?slug=<?=rawurlencode($a['slug'])?>">Məqaləni oxu ↗</a></div></article><?php endforeach;?></div><div class="pagination"><?php if($page>1):?><a href="<?=h(queryUrl(['page'=>$page-1]))?>">← Əvvəlki</a><?php endif;?><span><?=$page?> / <?=$pages?></span><?php if($page<$pages):?><a href="<?=h(queryUrl(['page'=>$page+1]))?>">Növbəti →</a><?php endif;?></div><?php else:?><div class="empty-content">Axtarışınıza uyğun dərc edilmiş məqalə tapılmadı.</div><?php endif;?></section></main>
